using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using VisualRelay.Core.Configuration;
using VisualRelay.Core.Init;

namespace VisualRelay.App.ViewModels;

public partial class MainWindowViewModel
{
    // ── Ceiling timeout bump ──────────────────────────────────────────────

    /// <summary>True when the selected task's latest error mentions the absolute ceiling.</summary>
    public bool IsCeilingTimeoutError =>
        SelectedTaskError?.Contains("absolute ceiling", StringComparison.OrdinalIgnoreCase) == true;

    /// <summary>Exposed for tests so they can assert CanExecute state.</summary>
    public bool CanBumpCeilingPublic => CanBumpCeiling();

    [RelayCommand(CanExecute = nameof(CanBumpCeiling))]
    private async Task BumpCeilingAsync()
    {
        IsBusy = true;
        try
        {
            var config = await RelayConfigLoader.LoadAsync(RootPath, CancellationToken.None);
            var newTimeout = config.SubagentTimeoutMilliseconds + 600_000;
            RelayConfigWriter.UpsertSubagentTimeout(RootPath, newTimeout);
            var minutes = newTimeout / 60_000;
            StatusText = $"Stage timeout raised to {minutes}m — applies from the next run.";
        }
        catch (Exception ex)
        {
            StatusText = $"Couldn't update timeout: {ex.Message}";
        }
        finally
        {
            IsBusy = false;
        }
    }

    private bool CanBumpCeiling() =>
        IsCeilingTimeoutError
        && !IsBusy
        && !string.IsNullOrEmpty(RootPath);

    // Hook: when SelectedTaskError changes (set by OnSelectedTaskChanged in
    // RunHistory.cs and RefreshSelectedTaskErrorAfterRun in LiveState.cs),
    // re-evaluate IsCeilingTimeoutError so the banner's button visibility updates.
    partial void OnSelectedTaskErrorChanged(string? value)
    {
        OnPropertyChanged(nameof(IsCeilingTimeoutError));
        BumpCeilingCommand.NotifyCanExecuteChanged();
    }
}

using System.Text.Json;
using System.Text.Json.Nodes;

namespace VisualRelay.Core.Init;

// Writes a minimal valid .relay/config.json with the given test command and an
// empty logSources array (so the loader treats it as Loaded). Overwrites any
// existing file at that path; callers gate on status before invoking.
// Pass null for testCommand to write "testCmd": null — the loader treats this
// as Incomplete, which is the deliberate exhaustion signal.
public static class RelayConfigWriter
{
    public static string Write(string rootPath, string? testCommand)
    {
        var relayDir = Path.Combine(rootPath, ".relay");
        Directory.CreateDirectory(relayDir);
        RelayGitignoreWriter.EnsureWritten(rootPath);

        var json = new JsonObject
        {
            ["testCmd"] = testCommand is not null
                ? JsonValue.Create(testCommand)
                : null,
            ["logSources"] = new JsonArray()
        };

        // Pin testFileCmd to the resolved testCmd instead of letting it inherit
        // the global "bun test {files}" default. The default leaks a Bun-shaped
        // targeted command into the stage agent's prompt, which makes greenfield
        // agents on Go/Python repos assume the project uses Bun and write .test.ts
        // junk. Using testCmd verbatim is correct (run the full suite for a changed
        // file, just less targeted) and never mentions bun; with no {files} token
        // the targeted-command builder cleanly falls back to testCmd. Only set it
        // when a real/placeholder command exists — a null testCmd is the deliberate
        // "Incomplete" exhaustion signal and must not gain a testFileCmd.
        if (testCommand is not null)
        {
            json["testFileCmd"] = JsonValue.Create(testCommand);
        }

        // Auto-detect guard command when guard scripts exist.
        var guardCmd = GuardCommandDetector.Detect(rootPath);
        if (guardCmd is not null)
        {
            json["guardCmd"] = JsonValue.Create(guardCmd);
        }

        // Auto-detect format command for the detected toolchain.
        var formatCmd = FormatCommandDetector.Detect(rootPath);
        if (formatCmd is not null)
        {
            json["formatCmd"] = JsonValue.Create(formatCmd);
        }

        var path = Path.Combine(relayDir, "config.json");
        File.WriteAllText(path, json.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + Environment.NewLine);
        return path;
    }

    /// <summary>
    /// Read-modify-write upgrade of a greenfield/placeholder config to the real,
    /// now-detectable toolchain commands: sets <c>testCmd</c> and fills in
    /// <c>formatCmd</c>/<c>guardCmd</c> from detection when they are not already
    /// present. Preserves every other key (tierProfiles, …) so an upgrade never
    /// clobbers settings the operator changed after bootstrap.
    /// </summary>
    public static void UpsertResolvedToolchain(string rootPath, string testCommand)
    {
        var relayDir = Path.Combine(rootPath, ".relay");
        Directory.CreateDirectory(relayDir);
        var json = ReadOrCreateConfig(relayDir, out var path);

        json["testCmd"] = testCommand;

        // Re-derive testFileCmd from the now-real testCmd. The initial bootstrap
        // wrote testFileCmd = placeholder (see Write); on upgrade it must track the
        // real command so the upgraded config carries no placeholder/bun-shaped
        // targeted command. Mirrors Write: testCmd verbatim, never "bun".
        json["testFileCmd"] = testCommand;

        // Now that a real toolchain exists, fill in the format/guard commands —
        // but never overwrite values the operator already set.
        if (json["formatCmd"] is null && FormatCommandDetector.Detect(rootPath) is { } formatCmd)
        {
            json["formatCmd"] = formatCmd;
        }
        if (json["guardCmd"] is null && GuardCommandDetector.Detect(rootPath) is { } guardCmd)
        {
            json["guardCmd"] = guardCmd;
        }

        File.WriteAllText(path, json.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + Environment.NewLine);
    }

    /// <summary>
    /// Read-modify-write upsert of the <c>commitProofArtifacts</c> key into
    /// <c>.relay/config.json</c>. Preserves all existing keys (testCmd,
    /// tierProfiles, baselineVerify, etc.) so toggling the checkbox never
    /// clobbers other settings.
    /// </summary>
    public static void UpsertCommitProofArtifacts(string rootPath, bool commitProofArtifacts)
    {
        var relayDir = Path.Combine(rootPath, ".relay");
        Directory.CreateDirectory(relayDir);
        var json = ReadOrCreateConfig(relayDir, out var path);

        json["commitProofArtifacts"] = commitProofArtifacts;

        File.WriteAllText(path, json.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + Environment.NewLine);
    }

    /// <summary>
    /// Read-modify-write upsert of the <c>subagentTimeoutMs</c> key into
    /// <c>.relay/config.json</c>. Preserves all existing keys.
    /// </summary>
    public static void UpsertSubagentTimeout(string rootPath, int milliseconds)
    {
        var relayDir = Path.Combine(rootPath, ".relay");
        Directory.CreateDirectory(relayDir);
        var json = ReadOrCreateConfig(relayDir, out var path);

        json["subagentTimeoutMs"] = milliseconds;

        File.WriteAllText(path, json.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + Environment.NewLine);
    }

    /// <summary>
    /// Read-modify-write upsert of the <c>boostTurnsTaskIds</c> JSON array into
    /// <c>.relay/config.json</c>. Adds or removes <paramref name="taskId"/>,
    /// de-duplicating entries, while preserving all other keys.
    /// </summary>
    public static void SetTurnBoost(string rootPath, string taskId, bool enabled)
    {
        var relayDir = Path.Combine(rootPath, ".relay");
        Directory.CreateDirectory(relayDir);
        var json = ReadOrCreateConfig(relayDir, out var path);

        // Get or create the boostTurnsTaskIds array.
        var array = json["boostTurnsTaskIds"] as JsonArray;
        if (array is null)
        {
            array = new JsonArray();
            json["boostTurnsTaskIds"] = array;
        }

        if (enabled)
        {
            // Add taskId if not already present (de-duplicate).
            if (!array.Any(node => node is JsonValue v && v.TryGetValue(out string? existing) && string.Equals(existing, taskId, StringComparison.Ordinal)))
            {
                array.Add(JsonValue.Create(taskId));
            }
        }
        else
        {
            // Remove all occurrences of taskId.
            var toRemove = new List<JsonNode?>();
            foreach (var node in array)
            {
                if (node is JsonValue v && v.TryGetValue(out string? existing) && string.Equals(existing, taskId, StringComparison.Ordinal))
                {
                    toRemove.Add(node);
                }
            }
            foreach (var node in toRemove)
            {
                array.Remove(node);
            }
        }

        File.WriteAllText(path, json.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + Environment.NewLine);
    }

    /// <summary>
    /// Read-modify-write upsert of the <c>skipTestsTaskIds</c> JSON array into
    /// <c>.relay/config.json</c>. Adds or removes <paramref name="taskId"/>,
    /// de-duplicating entries, while preserving all other keys.
    /// </summary>
    public static void SetSkipTests(string rootPath, string taskId, bool enabled)
    {
        var relayDir = Path.Combine(rootPath, ".relay");
        Directory.CreateDirectory(relayDir);
        var json = ReadOrCreateConfig(relayDir, out var path);

        // Get or create the skipTestsTaskIds array.
        var array = json["skipTestsTaskIds"] as JsonArray;
        if (array is null)
        {
            array = new JsonArray();
            json["skipTestsTaskIds"] = array;
        }

        if (enabled)
        {
            // Add taskId if not already present (de-duplicate).
            if (!array.Any(node => node is JsonValue v && v.TryGetValue(out string? existing) && string.Equals(existing, taskId, StringComparison.Ordinal)))
            {
                array.Add(JsonValue.Create(taskId));
            }
        }
        else
        {
            // Remove all occurrences of taskId.
            var toRemove = new List<JsonNode?>();
            foreach (var node in array)
            {
                if (node is JsonValue v && v.TryGetValue(out string? existing) && string.Equals(existing, taskId, StringComparison.Ordinal))
                {
                    toRemove.Add(node);
                }
            }
            foreach (var node in toRemove)
            {
                array.Remove(node);
            }
        }

        File.WriteAllText(path, json.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + Environment.NewLine);
    }

    /// <summary>
    /// Read-modify-write upsert of the <c>tierModelOverrides</c> key into
    /// <c>.relay/config.json</c>. Preserves all existing keys.
    /// </summary>
    public static void UpsertTierModelOverrides(string rootPath, IReadOnlyDictionary<string, string> overrides)
    {
        var relayDir = Path.Combine(rootPath, ".relay");
        Directory.CreateDirectory(relayDir);
        var json = ReadOrCreateConfig(relayDir, out var path);

        var obj = new JsonObject();
        foreach (var (tier, model) in overrides)
            obj[tier] = model;
        json["tierModelOverrides"] = obj;

        File.WriteAllText(path, json.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + Environment.NewLine);
    }

    // ── Private helpers ────────────────────────────────────────────────────

    /// <summary>
    /// Reads the existing <c>.relay/config.json</c> as a <see cref="JsonObject"/>,
    /// or returns a new empty object when the file is missing or malformed.
    /// </summary>
    private static JsonObject ReadOrCreateConfig(string relayDir, out string path)
    {
        path = Path.Combine(relayDir, "config.json");
        if (File.Exists(path))
        {
            var existing = JsonNode.Parse(File.ReadAllText(path));
            return existing as JsonObject ?? new JsonObject();
        }
        return new JsonObject();
    }
}

